<script setup>import{ref}from'vue';import data from '../experiments/artifacts/10/hierarchy_sweep.json';import{hierarchySweepPoint}from'./architectureModels.mjs';const artifact=data.variants.baseline,result=ref(artifact),mode=ref('artifact');function load(){result.value=artifact;mode.value='artifact'}function run(){result.value=hierarchySweepPoint({workloadBytes:data.workload_bytes,hitRate:artifact.hit_rate,queueDepth:artifact.queue_depth,baseCycles:data.base_cycles});mode.value=JSON.stringify(result.value)===JSON.stringify(artifact)?'matched':'mismatch'}</script>
<template><section class="baseline arch-overlay"><header><b>REPRODUCIBLE BASELINE</b><code>artifacts/10/hierarchy_sweep.json</code></header><div class="flow"><span>workload_bytes<b>{{data.workload_bytes}}</b></span><i>→</i><span>queue_depth<b>{{result.queue_depth}}</b></span><i>→</i><span>total_cycles<b>{{result.total_cycles}}</b></span></div><footer><button :class="{active:mode==='artifact'}" @click="load">Load artifact</button><button @click="run">Run JS model</button><strong>{{mode==='matched'?'✓ model reproduced artifact':mode==='artifact'?'✓ export-safe artifact baseline':'✕ model/artifact mismatch'}}</strong></footer></section></template>
